package com.example.aymobiledigitallibrary.ui.screens
import androidx.compose.foundation.layout.*;import androidx.compose.material3.*;import androidx.compose.runtime.*;import androidx.compose.ui.Alignment;import androidx.compose.ui.Modifier;import androidx.compose.ui.unit.dp;import com.example.aymobiledigitallibrary.model.DistractorAnswer;import com.example.aymobiledigitallibrary.ui.components.*
@Composable fun ShortActivityScreen(numbers:List<Int>,onDone:(List<DistractorAnswer>)->Unit){var i by remember{ mutableIntStateOf(0)};var sel by remember{ mutableStateOf<String?>(null)};var start by remember{ mutableLongStateOf(System.currentTimeMillis())};val ans=remember{ mutableStateListOf<DistractorAnswer>()};val n=numbers[i];ScreenContainer{TaskProgressHeader("Short Activity",i+1,numbers.size);QuestionCard{Text("Complete this brief activity before continuing.");Text("Is the following number even or odd?");Text("$n",style=MaterialTheme.typography.headlineLarge,modifier=Modifier.align(Alignment.CenterHorizontally));Row(horizontalArrangement=Arrangement.spacedBy(12.dp)){ChoiceButton("Even",sel=="Even"){sel="Even"};ChoiceButton("Odd",sel=="Odd"){sel="Odd"}};PrimaryButton("Continue", enabled=sel!=null){val c=if(n%2==0)"Even" else "Odd";ans+=DistractorAnswer(i+1,n,c,sel!!,System.currentTimeMillis()-start,c==sel); if(i==numbers.lastIndex) onDone(ans) else {i++;sel=null;start=System.currentTimeMillis()}}}}}
